  "CREATE TABLE IF NOT EXISTS `course_registry_events` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`type` text NOT NULL,\n\t`course_id` text NOT NULL,\n\t`revision` integer NOT NULL,\n\t`digest` text NOT NULL,\n\t`actor` text NOT NULL,\n\t`detail_json` text NOT NULL,\n\t`created_at` text NOT NULL\n);",
